// ─── CORSO 13: En Primeur Avanzato ──────────────────────────────────────────
export const EN_PRIMEUR_AVANZATO_MODULES = buildModules(13, "En Primeur Avanzato", [
  { t: "La Campagna En Primeur: Anatomia e Calendar", ctx: "Il meccanismo completo della campagna en primeur di Bordeaux: dal vendemmia al prezzo di release, come partecipare professionalmente.", dd: "La campagna en primeur si svolge ogni primavera (marzo-maggio) per l'annata precedente. I châteaux rilasciano le bottiglie a tranche (tranches) a prezzi crescenti. La prima tranche è sempre la più economica ma richiede di scommettere sulla qualità prima che i vini siano affinati. I négociants acquistano dai châteaux e rivendono a merchants globali con markup del 5-15%.", quiz: [{q:"La prima tranche en primeur è:", o:["La più cara","La più economica","Accessibile solo agli istituzionali","Venduta solo in Francia"], c:1},{q:"La campagna en primeur si svolge ogni:", o:["Autunno","Inverno","Primavera","Estate"], c:2},{q:"I négociants guadagnano tipicamente:", o:["0%","2-3%","5-15%","30%+"], c:2},{q:"Il rischio principale dell'en primeur è:", o:["Il prezzo potrebbe scendere","Il vino non esiste ancora fisicamente","Il cambio valutario","La conservazione"], c:1},{q:"L'en primeur è disponibile principalmente per:",o:["Tutti i vini del mondo","Solo Bordeaux (predominante)","Solo Borgogna","Solo vini italiani"],c:1}] },
  { t: "Pricing En Primeur: Come Valutare se il Prezzo è Giusto", ctx: "Il framework per determinare se un prezzo en primeur offre valore reale rispetto al mercato secondario atteso.", dd: "La formula base: se il prezzo en primeur + costi di storage per X anni è inferiore al prezzo atteso nel mercato secondario al momento del consumo ottimale, l'en primeur offre valore. Storicamente, le annate 2009 e 2010 offrivano valore reale; le annate 2019-2022 sono state generalmente overpriced rispetto al secondario.", quiz: [{q:"Quando l'en primeur offre valore:",o:["Sempre","Quando EP+costi < prezzo secondario atteso","Solo per annate 90+ Parker","Quando il franco svizzera si apprezza"],c:1},{q:"Le annate 2009 e 2010 en primeur sono considerate:",o:["Overpriced","Buon valore — ora valgono 3x il prezzo EP","Scadenti","Non disponibili"],c:1},{q:"I costi di storage da includere nel calcolo sono:",o:["Nessuno se hai garage","€10-15 per cassa/anno","€50-100 per cassa/anno","€500 per cassa/anno"],c:2},{q:"Il markup dei négociants è incluso nel prezzo:",o:["No — si paga separatamente","Sì, sempre incluso","Solo per grands châteaux","Dipende dall'annata"],c:0},{q:"Le annate 2019-2022 en primeur sono state generalmente:",o:["Sottovalutate","Overpriced rispetto al secondario","In linea con il mercato","Non ancora valutabili"],c:1}] },
  { t: "Négociants e Place de Bordeaux: Il Sistema", ctx: "Come funziona la Place de Bordeaux: le 300+ case négociant che intermediano tra châteaux e mercato globale.", dd: "La Place de Bordeaux è un sistema quasi-feudale di distribuzione. I châteaux vendono solo attraverso négociants accreditati (circa 300). I negociants principali: CVBG, Millésima, Berry Bros & Rudd, Corney & Barrow. Ogni négociant ha allocazioni diverse da châteaux diverse. L'accesso alle migliori allocazioni dipende dal volume acquistato negli anni precedenti.", quiz: [{q:"Quante case négociant fanno parte della Place de Bordeaux?",o:["10-20","50-100","300+","1.000+"],c:2},{q:"Chi può vendere direttamente senza négociants?",o:["Nessuno — sistema chiuso","Solo i Premier Grand Cru","Qualsiasi châteaux che vuole","Solo i châteaux biologici"],c:0},{q:"L'accesso alle migliori allocazioni dipende da:",o:["Il budget del singolo acquisto","Il volume acquistato negli anni precedenti","La nazionalità dell'acquirente","La relazione personale col proprietario"],c:1},{q:"Berry Bros & Rudd è:",o:["Un'auction house","Un négociant storico inglese","Un insurance provider","Un wine fund"],c:1},{q:"Il sistema Place de Bordeaux è vantaggioso per:",o:["Gli acquirenti finali (prezzi bassi)","I châteaux (distribuzione capillare)","I consumer finali (accesso diretto)","Le istituzioni finanziarie"],c:1}] },
  ...Array.from({length:17}, (_,i) => ({ t: ["Due Diligence Prima di Comprare En Primeur","Il Ruolo dei Critici: Parker, Jancis, Suckling","Traduzione Punteggi in Decisioni di Acquisto","Modalità di Pagamento e Delivery","En Primeur Bordeaux vs. Resto del Mondo","Risk Management: Châteaux che Non Consegnano","Storage e Assicurazione per Vini EP","Rivenderò o Berò? Strategia a Lungo Termine","Gestire un Portfolio EP da €10k a €100k","Analisi delle Annate EP 2015-2024","Il Mercato Secondario dopo l'EP","En Primeur: Errori Comuni e Come Evitarli","Workshop: Simulazione Acquisto EP","Tool: VinoInvest EP Calculator","Certificazione En Primeur Specialist","Il Futuro dell'En Primeur nel 2030","Recap e Piano d'Azione Personale"][i], ctx: `Modulo ${i+4} approfondimento en primeur`, dd: `Contenuto professionale modulo ${i+4} del corso En Primeur Avanzato.`, quiz: Array.from({length:5},(_,q)=>({q:`Domanda ${q+1}`,options:["A","B","C","D"],correct:q%4})) })),
]);

// ─── CORSO 14: Autenticità e Provenienza ────────────────────────────────────
export const AUTENTICITA_PROVENIENZA_MODULES = buildModules(14, "Autenticità e Provenienza", [
  { t: "Il Mercato della Contraffazione: Scala e Impatto", ctx: "La contraffazione nel fine wine è un mercato da $3 miliardi/anno. Come si manifesta e perché è difficile da rilevare.", dd: "Il caso Rudy Kurniawan (condannato nel 2013) ha evidenziato la vulnerabilità del mercato: bottiglie contraffatte di DRC, Petrus e Ponsot avevano ingannato esperti e collezionisti per anni. La contraffazione moderna usa etichette autentiche su vini diversi, ricorking di annate recenti, e bottiglie genuine riempite con vini inferiori. Il danno al mercato è stimato in $3 miliardi annui, pari al 3-4% del mercato globale.", quiz: [{q:"Il valore stimato della contraffazione nel fine wine è:",o:["$10 milioni","$500 milioni","$3 miliardi","$50 miliardi"],c:2},{q:"Rudy Kurniawan è famoso per:",o:["Aver fondato Liv-ex","La più grande frode di vini contraffatti della storia","Aver creato il sistema en primeur","Aver inventato il Barolo"],c:1},{q:"La contraffazione moderna usa principalmente:",o:["Vini completamente falsi","Etichette autentiche su vini diversi e ricorking","Bottiglie fatte in plastica","Vini di regioni diverse con etichette false"],c:1},{q:"La contraffazione rappresenta circa:",o:["0.1% del mercato","3-4% del mercato globale","20% del mercato","50% delle bottiglie > €500"],c:1},{q:"Quale è il livello di prezzo più colpito dalla contraffazione?",o:["Vini < €20","Vini €20-100","Vini > €200 (DRC, Petrus, 1ere Crus)","Tutti i livelli ugualmente"],c:2}] },
  { t: "Verifica dell'Autenticità: Metodi Fisici", ctx: "Tecniche pratiche per verificare l'autenticità di una bottiglia: capsule, livello, etichetta, cork, vetro.", dd: "L'autenticità fisica si verifica su 5 elementi: (1) Livello del vino (ullage) — deve essere neck o into neck per vini > 20 anni. (2) Capsule — originale non perforata, senza segni di manomissione. (3) Etichetta — font corretto per l'annata, carta invecchiata naturalmente, non stampata su carta nuova. (4) Cork — visibile attraverso la capsula, deve avere l'anno stampato. (5) Vetro — peso e colore corretti per il produttore.", quiz: [{q:"L'ullage 'neck' indica:",o:["Il vino è quasi finito","Il livello è corretto per un vino giovane","Il vino è stato diluito","Un difetto della bottiglia"],c:1},{q:"Un'etichetta stampata su carta nuova su una bottiglia dichiarata 1990 è:",o:["Normale — le etichette vengono sostituite","Un forte red flag di contraffazione","Pratica comune per i vini old vintage","Un indicatore di qualità superiore"],c:1},{q:"La capsule deve essere:",o:["Perforata per ossigenare","Non perforata, senza segni di manomissione","Rimovibile facilmente","Uguale per tutti i produttori"],c:1},{q:"Il cork deve avere:",o:["Solo il colore corretto","L'anno stampato — verificabile con torcia","La firma del winemaker","Nessun segno — è sigillato"],c:1},{q:"Per vini > 20 anni, il livello accettabile è:",o:["Base del collo o sopra","Mid-shoulder (a metà spalla)","Low-shoulder (bassa spalla)","Qualsiasi livello è accettabile"],c:0}] },
  ...Array.from({length:18}, (_,i) => ({ t: ["Verifica con Luce UV e Spettroscopia","La Catena di Custodia (Provenance Chain)","OWC Originale: Valore e Certificazione","Aste e Provenienza: Standard Internazionali","Certificati Digitali e Blockchain per il Vino","I Lab di Autenticazione (Eurofins, AWA)","Red Flags: Come Riconoscere una Bottiglia Sospetta","Case Study: Le Frodi più Famose della Storia","Due Diligence per Acquisti Private","Assicurazione e Valutazione per Bottiglie Rare","I Diritti Legali dell'Acquirente in Caso di Frode","Tecnologie Anti-Contraffazione dei Produttori","NFC e QR Code per la Tracciabilità","Workshop: Esaminare una Bottiglia Reale","Costruire un Registro di Provenienza Personale","Il Futuro dell'Autenticità nel Fine Wine","Checklist Definitiva Pre-Acquisto","Certificazione Authenticator"][i], ctx: `Modulo ${i+3} autenticità`, dd: `Approfondimento professionale autenticità e provenienza — modulo ${i+3}.`, quiz: Array.from({length:5},(_,q)=>({q:`Domanda ${q+1}`,options:["A","B","C","D"],correct:q%4})) })),
]);

// ─── HELPER per moduli compatti ──────────────────────────────────────────────
function buildModules(courseId, courseTitle, rawModules) {
  return rawModules.map((m, i) => ({
    id: `c${courseId}_${String(i + 1).padStart(2, "0")}`,
    courseId,
    index: i,
    title: m.t,
    duration: m.dur || 13,
    youtube: null,
    hero: { headline: m.t, stat: m.stat || "", context: `${courseTitle} — Modulo ${i + 1} di 20` },
    objectives: m.obj || ["Analizzare il tema", "Applicare le tecniche", "Costruire la strategia", "Misurare i risultati"],
    context: m.ctx || `${courseTitle} — modulo ${i + 1}`,
    slides: m.slides || Array.from({ length: 8 }, (_, s) => ({ title: `Sezione ${s + 1}`, body: `${m.t} — sezione ${s + 1}.` })),
    mapSvg: `<svg viewBox="0 0 400 180" xmlns="http://www.w3.org/2000/svg"><rect width="400" height="180" fill="#0b1220"/><text x="200" y="90" textAnchor="middle" fill="#C9A227" fontSize="14" fontFamily="serif">${courseTitle}</text><text x="200" y="115" textAnchor="middle" fill="#ffffff88" fontSize="10">Modulo ${i + 1}</text></svg>`,
    deepDive: m.dd || `Modulo ${i + 1}: ${m.t}. Approfondimento professionale.`,
    caseStudies: m.cs || [],
    techniques: m.tech || [],
    exercise: m.ex || { title: `Esercizio Modulo ${i + 1}`, steps: ["Analizzare il caso", "Applicare il framework", "Documentare i risultati"] },
    keyPoints: m.kp || [`Punto chiave 1 del modulo ${i + 1}`, `Punto chiave 2`, `Punto chiave 3`],
    quiz: m.quiz || Array.from({ length: 5 }, (_, q) => ({ q: `Domanda ${q + 1}`, options: ["A", "B", "C", "D"], correct: q % 4 })),
  }));
}

const compact = (courseId, title, titles20) =>
  buildModules(courseId, title, titles20.map(t => ({ t })));

// ─── CORSO 15: Tax e Legale ──────────────────────────────────────────────────
export const TAX_LEGALE_MODULES = buildModules(15, "Tax e Legale", [
  { t: "Il Quadro Fiscale del Fine Wine in Italia", ctx: "Come il sistema fiscale italiano tratta il fine wine: capital gain, IVA, dichiarazione dei redditi.", dd: "In Italia, il fine wine è classificato come bene mobile non produttivo di reddito se detenuto per uso personale. Le plusvalenze da vendita sono soggette a imposta del 26% (capital gain su beni mobili). Tuttavia, se il vino è acquistato per investimento e venduto con frequenza, l'attività potrebbe essere qualificata come commerciale, con aliquota IRPEF progressiva. Strategia ottimale: documentare l'acquisto come collezionismo, limitare le vendite annuali.", quiz: [{q:"L'aliquota capital gain su beni mobili in Italia è:",o:["12.5%","19%","26%","43%"],c:2},{q:"Il fine wine in Italia è classificato come:",o:["Attività finanziaria","Bene mobile non produttivo di reddito (uso personale)","Immobile","Derivato finanziario"],c:1},{q:"Quando l'attività di vendita vino diventa 'commerciale':",o:["Sempre","Quando si vende con frequenza e per profitto sistematico","Solo sopra €100k/anno","Mai"],c:1},{q:"La strategia fiscale ottimale è:",o:["Vendere tutto entro l'anno","Documentare come collezionismo e limitare vendite annuali","Non dichiarare","Aprire una SRL"],c:1},{q:"L'IVA sul vino acquistato per investimento è:",o:["Non detraibile (uso personale)","Detraibile al 100%","Detraibile al 50%","Non applicabile"],c:0}] },
  { t: "Fiscalità Internazionale: UK, USA, Francia", ctx: "Come i principali paesi del fine wine trattano il capital gain: il vantaggio del UK per gli investitori.", dd: "Il UK offre il trattamento fiscale più favorevole: il fine wine è classificato come 'wasting asset' (vita utile < 50 anni) ed è quindi esente da Capital Gains Tax. Questa è la ragione principale per cui London è il hub globale del fine wine investing. USA: collectibles CGT del 28%. Francia: exonération se detenuto > 2 anni e vendita < €5.000 (altrimenti 36.2% con CSG). Per investitori internazionali, la struttura fiscale ottimale è attraverso una holding UK o Irish entity.", quiz: [{q:"Il UK tassa il capital gain sul fine wine?",o:["Sì, 20% flat","Sì, 28% (collectibles)","No — è esente come wasting asset","Sì, 40% per higher rate taxpayers"],c:2},{q:"La classificazione 'wasting asset' nel UK richiede:",o:["Il vino sia di bassa qualità","La vita utile prevista < 50 anni","Il valore sia < £5.000","Il vino sia acquistato all'asta"],c:1},{q:"L'aliquota CGT USA per i collectibles (incluso fine wine) è:",o:["15%","20%","28%","35%"],c:2},{q:"La struttura ottimale per un investitore internazionale è:",o:["Acquistare in Italia","Holding UK o Irish entity","Trust svizzero","LLC americana"],c:1},{q:"In Francia, la vendita è esente se:",o:["Sempre esente","Detenuto > 2 anni E vendita < €5.000","Solo per Bordeaux","Detenuto > 10 anni"],c:1}] },
  ...Array.from({length:18}, (_,i) => ({ t: ["IVA e Accise: Import/Export di Fine Wine","Strutturare un'Eredità di Vino","Trust e Società per la Detenzione di Wine Assets","Insurance: Valutazione e Copertura Corretta","Assicurazione per Trasporti Internazionali","Due Diligence Legale Prima dell'Acquisto","Contratti di Vendita Privata: Clausole Chiave","Dispute Resolution nel Fine Wine","La Normativa Wine Merchant in Europa","GDPR e Privacy per Merchant e Collector","Anti-Money Laundering (AML) nel Fine Wine","Importare Vino Extra-UE: Dazi e Procedure","Esportare Fine Wine: Documentazione Richiesta","NFT e Tokenizzazione del Vino: Aspetti Legali","La Regolamentazione delle Auction House","Fraud Prevention: Tutele Legali dell'Acquirente","Pianificazione Patrimoniale con Fine Wine","Certificazione Tax & Legal Specialist"][i], ctx: `Modulo ${i+3} tax e legale`, dd: `Approfondimento fiscale e legale — modulo ${i+3}.`, quiz: Array.from({length:5},(_,q)=>({q:`Domanda ${q+1}`,options:["A","B","C","D"],correct:q%4})) })),
]);

// ─── CORSO 16: Mercato Secondario e Liquidità ────────────────────────────────
export const MERCATO_SECONDARIO_MODULES = buildModules(16, "Mercato Secondario e Liquidità", [
  { t: "La Struttura del Mercato Secondario Globale", ctx: "Anatomia del mercato secondario del fine wine: auction houses, exchange, merchant, privato. Chi sono i player e come interagiscono.", dd: "Il mercato secondario del fine wine ha un valore stimato di $6-8 miliardi/anno (2024). I canali principali: aste fisiche (Christie's, Sotheby's, Bonhams, Hart Davis Hart) con il 40% del volume; exchange B2B (Liv-ex) con 30%; merchant-to-merchant con 20%; privato 10%. La liquidità varia enormemente: DRC si vende in ore su Liv-ex, vini regionali minori possono richiedere settimane su asta.", quiz: [{q:"Il valore stimato del mercato secondario fine wine è:",o:["$500 milioni","$2 miliardi","$6-8 miliardi","$50 miliardi"],c:2},{q:"La quota aste fisiche sul volume secondario è circa:",o:["10%","40%","70%","90%"],c:1},{q:"Liv-ex è:",o:["Un'auction house","Un exchange B2B per professional buyers","Un wine magazine","Un fondo di investimento"],c:1},{q:"La liquidità più alta sul mercato secondario ce l'hanno:",o:["I vini regionali italiani","I Super Tuscans entry level","DRC e Petrus","Tutti i vini allo stesso modo"],c:2},{q:"Il canale privato rappresenta circa:",o:["50%","30%","10%","0%"],c:2}] },
  { t: "Liv-ex: Come Funziona il Trade sul'Exchange", ctx: "Il funzionamento operativo di Liv-ex: account, listing, offer, settlement, e le regole del mercato B2B.", dd: "Liv-ex (London International Vintners Exchange) è il mercato B2B professionale per il fine wine. Richiede membership (£5.000/anno per i livelli base). Il sistema funziona con bid/offer: un seller posta un'offer price, un buyer posta un bid, quando si incrociano la transazione è automatica. Settlement: 30 giorni. Shipping: organizzato da Liv-ex. Il Liv-ex Fine Wine 100 è calcolato quotidianamente basandosi sulle transazioni reali sul mercato.", quiz: [{q:"La membership annuale base di Liv-ex è circa:",o:["Gratuita","£500","£5.000","£50.000"],c:2},{q:"Il settlement period su Liv-ex è:",o:["Immediato (T+0)","T+3 come equity","30 giorni","60 giorni"],c:2},{q:"Il Liv-ex Fine Wine 100 è calcolato:",o:["Mensilmente (sondaggi)","Quotidianamente su transazioni reali","Annualmente","Solo in aprile (en primeur)"],c:1},{q:"Chi può accedere a Liv-ex?",o:["Chiunque con carta di credito","Solo i grandi auction house","Professional buyers con membership","Solo i négociants francesi"],c:2},{q:"Quando si incroca bid e offer su Liv-ex:",o:["Il sistema avvisa e aspetta approvazione","La transazione è automatica","Si negozia il prezzo finale","Si va all'asta"],c:1}] },
  ...Array.from({length:18}, (_,i) => ({ t: ["Christie's e Sotheby's: Come Partecipare alle Aste","Bonhams, WineBid e le Auction House Minori","Commissioni Totali: Calcolo del Netto","Buyer's Premium vs Seller's Commission","Come Creare un Account da Seller alle Aste","Hammer Price vs Estimate Price: Come Funzionano","Lot Building: Come Massimizzare il Prezzo","Timing delle Aste: Quando Vendere","Reserved Price: Come Impostarlo","Due Diligence pre-Asta: Documentation","Ritiro del Lotto e Rimborso","Merchant Secondario: Pro e Contro","Peer-to-Peer: Piattaforme e Sicurezza","Liquidity Premium: Perché Alcuni Vini Pagano di Più","Bid Strategies per gli Acquirenti","Mercato Asiatico: Hong Kong e Singapore","USA: Hart Davis Hart e Zachys","Il Futuro del Mercato Secondario Online"][i], ctx: `Modulo ${i+3} mercato secondario`, dd: `Guida operativa al mercato secondario — modulo ${i+3}.`, quiz: Array.from({length:5},(_,q)=>({q:`Domanda ${q+1}`,options:["A","B","C","D"],correct:q%4})) })),
]);

// ─── CORSO 17: Data Analytics per Decisioni ─────────────────────────────────
export const DATA_ANALYTICS_MODULES = buildModules(17, "Data Analytics per Decisioni", [
  { t: "I Dati del Fine Wine: Fonti e Affidabilità", ctx: "Panoramica delle fonti di dati per il fine wine: Liv-ex, Wine-Searcher, Robert Parker, auction results. Come valutare l'affidabilità.", dd: "Le principali fonti di dati per l'analisi del fine wine: Liv-ex (prezzi transazioni B2B reali), Wine-Searcher (aggregazione prezzi retail globale), auction results (Christie's, Sotheby's — pubblici), Robert Parker Wine Advocate (punteggi), Decanter/Wine Spectator (punteggi alternativi). Ogni fonte ha bias diversi: Liv-ex copre solo vini con mercato attivo, Wine-Searcher include retail markup, auction results possono essere outlier. La combinazione di fonti è sempre preferibile alla fonte singola.", quiz: [{q:"La fonte di prezzi più affidabile per il mercato B2B è:",o:["Wine-Searcher","Robert Parker","Liv-ex (transazioni reali)","Instagram dei produttori"],c:2},{q:"Wine-Searcher aggrega principalmente:",o:["Prezzi all'asta","Prezzi retail di merchants globali","Prezzi en primeur","Valutazioni dei critici"],c:1},{q:"Un limite di Liv-ex è:",o:["Non copre il Bordeaux","Copre solo vini con mercato B2B attivo","I prezzi sono mensili","Non è affidabile"],c:1},{q:"Quando combinare più fonti di dati:",o:["Mai — una fonte è sufficiente","Sempre, per ridurre il bias della fonte singola","Solo per vini > €500","Solo per le aste"],c:1},{q:"I risultati d'asta possono essere 'outlier' perché:",o:["Sono sempre sopravvalutati","Una singola vendita con un buyer eccezionale può distorcere","I risultati sono falsi","Dipendono dalla stagione"],c:1}] },
  { t: "Python per l'Analisi del Wine Portfolio", ctx: "Come usare Python (pandas, matplotlib, seaborn) per analizzare un wine portfolio: rendimento, correlazioni, benchmark.", dd: "Python è lo strumento standard per l'analisi quantitativa del fine wine portfolio. Le librerie fondamentali: pandas per manipolazione dati, matplotlib/seaborn per visualizzazione, scipy per analisi statistica. Il workflow tipico: (1) importare dati da Liv-ex CSV o Wine-Searcher API, (2) calcolare rendimenti per posizione, (3) calcolare correlazioni inter-posizione, (4) benchmark vs Liv-ex 100, (5) stress test con scenari storici. VinoInvest fornisce export CSV del portfolio per uso con Python.", quiz: [{q:"La libreria Python per manipolazione dati è:",o:["numpy","pandas","matplotlib","sklearn"],c:1},{q:"Il primo step del workflow analytics è:",o:["Calcolare i rendimenti","Importare i dati (Liv-ex CSV o API)","Fare il benchmark","Vendere le posizioni peggiori"],c:1},{q:"Il benchmark naturale per un wine portfolio è:",o:["S&P 500","Liv-ex Fine Wine 100","FTSE 100","Gold spot price"],c:1},{q:"Uno 'stress test storico' sul wine portfolio simula:",o:["Cosa succederebbe se tutti i vini fossero difettosi","L'impatto di eventi passati (2008 crash, COVID) sul portfolio","Il rendimento se si vendesse oggi","Il costo di storage nel peggiore caso"],c:1},{q:"VinoInvest supporta export del portfolio in:",o:["Solo PDF","CSV (per analisi con Python/Excel)","Solo JSON API","Non supporta export"],c:1}] },
  ...Array.from({length:18}, (_,i) => ({ t: ["Excel per il Portfolio Manager (No Code)","Costruire un Dashboard di Portfolio","KPI Essenziali: IRR, MOIC, TWR","Correlation Matrix: Come Interpretarla","Backtesting Strategie sul Passato","Regression Analysis: Predire i Prezzi","Sentiment Analysis dei Critici con NLP","Time Series Analysis per i Prezzi","Cluster Analysis: Raggruppare i Vini","Machine Learning per il Rating Prediction","Visualizzazioni Efficaci per Investitori","Reporting Professionale per i Clienti","Automazione dei Report Mensili","API Integration: Liv-ex e Wine-Searcher","Database Design per il Wine Portfolio","Real-time Alerts: Prezzo Target","Dashboard B2B per Family Office","Certificazione Data Analyst Wine"][i], ctx: `Modulo ${i+3} data analytics`, dd: `Analisi dati applicata al fine wine — modulo ${i+3}.`, quiz: Array.from({length:5},(_,q)=>({q:`Domanda ${q+1}`,options:["A","B","C","D"],correct:q%4})) })),
]);

